window.MG_LAZY_DATA["data/lazy/owner-resources/b463-53f80998f27db3b4.json"]={sha256:"53f80998f27db3b42b36179079b745b6d7442658961f27b474705a7053baf35b",value:{"sources":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-urban-district","title":"區域供冷系統原理","titleEn":"About District Cooling Systems","url":"https://wcms.emsd.gov.hk/en/energy_efficiency/DCS_in_HK/about_dcs/index.html","organization":"Hong Kong EMSD","accessed":"2026-10-23","publisher":"Hong Kong EMSD","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-heat","title":"現場能源與熱泵技術","titleEn":"Onsite Energy Technologies","url":"https://betterbuildingssolutioncenter.energy.gov/onsite-energy/technologies","organization":"US DOE","accessed":"2026-10-23","publisher":"US DOE","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"media":{"courses":[{"courseId":"b463","videos":[],"guides":[{"id":"b463-v17-practice","title":"工程操作與定量驗證手冊","titleEn":"Engineering actions and quantitative verification","concept":"以「冷量傳輸、壓降與低溫差診斷」為主線，依序完成十個專題單元。學徒在場景中辨識設備、列出邊界、重算明示的教學算例、比較量測與模型，最後診斷故障並交付證據。每一單元保留機制、算例、驗證與失效四種學習任務。","conceptEn":"Follow cooling transfer, pressure loss and low-temperature-difference diagnosis through ten technical units. Identify equipment in the scene, define boundaries, reproduce explicitly hypothetical examples, compare measurements with models, and diagnose faults before handing over evidence. Each unit contains mechanism, calculation, verification and failure tasks.","procedure":["在「冷量與水流」的教學模型或試算表中先重現 501.6 kW，再依驗證任務改動一個輸入、保留其餘條件。對照「高流量低溫差可能仍傳送不足冷量。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「管徑與流速」的教學模型或試算表中先重現 1.13177 m/s，再依驗證任務改動一個輸入、保留其餘條件。對照「內徑與公稱管徑混用會偏移壓降估算。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「沿程壓降」的教學模型或試算表中先重現 19200 Pa，再依驗證任務改動一個輸入、保留其餘條件。對照「漏算換熱器和閥損會低估泵揚程。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「泵浦與電力」的教學模型或試算表中先重現 1.6 kW，再依驗證任務改動一個輸入、保留其餘條件。對照「用名牌最高效率代表所有負載會高估節能。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「低溫差症候群」的教學模型或試算表中先重現 39.8724 kg/s，再依驗證任務改動一個輸入、保留其餘條件。對照「閥常開或換熱器控制不良可能造成旁通混水。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「換熱器溫差推動」的教學模型或試算表中先重現 5.77078 K，再依驗證任務改動一個輸入、保留其餘條件。對照「只增加流量可能無法補救受限UA。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「管線熱增益」的教學模型或試算表中先重現 4 kW，再依驗證任務改動一個輸入、保留其餘條件。對照「保溫受潮可能同時增加熱損與腐蝕風險。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「蓄冷容量與削峰」的教學模型或試算表中先重現 696.667 kWh，再依驗證任務改動一個輸入、保留其餘條件。對照「總水量乘最大溫差會高估已混合水槽容量。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「多用戶同時率」的教學模型或試算表中先重現 0.8 fraction，再依驗證任務改動一個輸入、保留其餘條件。對照「用月帳單平均值估尖峰可能低估設備需求。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「熱量計誤差與交接」的教學模型或試算表中先重現 0.0666667 fraction，再依驗證任務改動一個輸入、保留其餘條件。對照「未配對校正探頭會把量測偏差當網路損失。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。"],"procedureEn":["In the teaching model or spreadsheet for cooling duty and flow, first reproduce 501.6 kW, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"High flow with low temperature difference can still deliver insufficient cooling.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for pipe diameter and velocity, first reproduce 1.13177 m/s, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Mixing internal and nominal diameters biases pressure loss.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for distributed pressure loss, first reproduce 19200 Pa, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Omitting exchanger and valve losses understates pump head.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for pumping and electricity, first reproduce 1.6 kW, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Using nameplate peak efficiency at every load overstates savings.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for low-delta-t syndrome, first reproduce 39.8724 kg/s, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Stuck-open valves or poor exchanger control can cause bypass mixing.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for heat-exchanger driving difference, first reproduce 5.77078 K, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"More flow may not compensate for limited UA.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for heat gain in pipes, first reproduce 4 kW, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Wet insulation can increase both thermal loss and corrosion concerns.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for thermal-storage capacity and peak shaving, first reproduce 696.667 kWh, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Total volume times maximum deltaT overstates a mixed tank.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for demand coincidence, first reproduce 0.8 fraction, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Monthly-average billing data can understate peak requirements.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for heat-meter uncertainty and handover, first reproduce 0.0666667 fraction, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Unmatched probe calibration can look like network loss.\" and submit baseline and changed values, units, and one measurement that distinguishes them."],"evidence":["改變溫差並保持流量，觀察冷量。","管徑減少10%，比較流速增加幅度。","將流速增加20%，重算平方效應。","同步記錄流量、壓差與耗電檢查效率。","比較DeltaT為3K與6K的流量需求。","比較清潔與污損時所需面積或流量。","比較保溫受潮前後的Uprime。","提高無效混合比例並比較可用削峰時數。","比較相加最大值與逐時加總後最大值。","交換兩支溫度探頭位置，檢查偏差方向。"],"evidenceEn":["Vary temperature difference at fixed flow and observe duty.","Reduce diameter ten percent and compare velocity increase.","Increase velocity20% and recalculate the square-law effect.","Record flow, pressure and electricity to check efficiency.","Compare required flow at3K and6K.","Compare clean/fouled area or flow requirements.","Compare line conductance before and after insulation wetting.","Increase mixing loss and compare usable peak-shaving hours.","Compare summed individual maxima with the maximum hourly sum.","Swap temperature probes and check bias direction."],"pitfalls":["高流量低溫差可能仍傳送不足冷量。","內徑與公稱管徑混用會偏移壓降估算。","漏算換熱器和閥損會低估泵揚程。","用名牌最高效率代表所有負載會高估節能。","閥常開或換熱器控制不良可能造成旁通混水。","只增加流量可能無法補救受限UA。","保溫受潮可能同時增加熱損與腐蝕風險。","總水量乘最大溫差會高估已混合水槽容量。","用月帳單平均值估尖峰可能低估設備需求。","未配對校正探頭會把量測偏差當網路損失。"],"pitfallsEn":["High flow with low temperature difference can still deliver insufficient cooling.","Mixing internal and nominal diameters biases pressure loss.","Omitting exchanger and valve losses understates pump head.","Using nameplate peak efficiency at every load overstates savings.","Stuck-open valves or poor exchanger control can cause bypass mixing.","More flow may not compensate for limited UA.","Wet insulation can increase both thermal loss and corrosion concerns.","Total volume times maximum deltaT overstates a mixed tank.","Monthly-average billing data can understate peak requirements.","Unmatched probe calibration can look like network loss."],"sourceIds":["v17s-urban-district","v17s-urban-heat"],"sources":[{"id":"v17s-urban-district","title":"區域供冷系統原理","titleEn":"About District Cooling Systems","url":"https://wcms.emsd.gov.hk/en/energy_efficiency/DCS_in_HK/about_dcs/index.html","organization":"Hong Kong EMSD","accessed":"2026-10-23","publisher":"Hong Kong EMSD","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-heat","title":"現場能源與熱泵技術","titleEn":"Onsite Energy Technologies","url":"https://betterbuildingssolutioncenter.energy.gov/onsite-energy/technologies","organization":"US DOE","accessed":"2026-10-23","publisher":"US DOE","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"simulationOnly":true,"scope":"公開原理與資料支持的原創教學。算例中的輸入為明示教學假設，非該設施實測或操作設定。此處任務在離線模型完成，不能作為現場設計、飲用水合格或設備操作許可。","scopeEn":"Original teaching based on public principles and sources. Numerical inputs are explicit teaching assumptions, not site measurements or operating setpoints. Tasks use offline models and do not certify field design, potable-water compliance or equipment operation."}]}]},"related":{"courses":[{"courseId":"b463","overview":"跨單元連結與比較練習","overviewEn":"Cross-process connections and comparisons","related":[{"id":"b415","title":"首爾清溪川復育","titleEn":"Seoul Cheonggyecheon restoration","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"首爾代表點","nameEn":"Seoul reference point","country":"南韓","countryEn":"South Korea","lat":37.57,"lon":126.98,"coordinateScope":"approximate-city-reference; not a facility entrance","lng":126.98,"coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]},{"id":"b416","title":"新加坡碧山—宏茂橋公園河川復育","titleEn":"Bishan–Ang Mo Kio Park river restoration","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"新加坡","nameEn":"Singapore","country":"新加坡","countryEn":"Singapore","lat":1.35,"lon":103.82,"coordinateScope":"approximate-city-reference; not a facility entrance","lng":103.82,"coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]}],"references":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-urban-district","title":"區域供冷系統原理","titleEn":"About District Cooling Systems","url":"https://wcms.emsd.gov.hk/en/energy_efficiency/DCS_in_HK/about_dcs/index.html","organization":"Hong Kong EMSD","accessed":"2026-10-23","publisher":"Hong Kong EMSD","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-heat","title":"現場能源與熱泵技術","titleEn":"Onsite Energy Technologies","url":"https://betterbuildingssolutioncenter.energy.gov/onsite-energy/technologies","organization":"US DOE","accessed":"2026-10-23","publisher":"US DOE","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}]}]},"places":{"courses":[{"courseId":"b463","place":{"name":"香港機電工程署九龍灣總部：方法資料來源機構（非實廠）","nameEn":"Hong Kong EMSD headquarters, Kowloon Bay: methodology source institution (not a process plant)","country":"中國香港","countryEn":"Hong Kong, China","lat":22.32,"lon":114.2,"coordinateScope":"近似機構所在區域位置；依公開地址作教材地圖代表點，非建物入口、實廠、實測或導航位置。","coordinateScopeEn":"Approximate institution-area location inferred from its public address for the teaching map; not a building entrance, process plant, surveyed point or navigation coordinate.","locationSourceUrl":"https://www.info.gov.hk/gia/general/202007/24/P2020072400753.htm","locationVerified":"2026-10-23","lng":114.2},"summary":"本課以來源所列的技術指引與研究為閱讀脈絡，並非重建某一設施的工程沿革；算例、數據與場景參數皆為原創教學假設。比較舊方法與感測、控制、資源回收整合的方法時，先固定處理功能及系統邊界，再評估效率與可靠度。","summaryEn":"The cited technical guidance and research provide a reading pathway, not the engineering history of a particular facility. Examples, data and scene parameters are original teaching assumptions. When comparing conventional methods with integrated sensing, control and resource recovery, hold the treatment function and system boundary fixed before assessing efficiency and reliability.","history":[{"year":"工程背景","title":"區域冷卻管網","titleEn":"District-cooling pipe networks","text":"本課以來源所列的技術指引與研究為閱讀脈絡，並非重建某一設施的工程沿革；算例、數據與場景參數皆為原創教學假設。比較舊方法與感測、控制、資源回收整合的方法時，先固定處理功能及系統邊界，再評估效率與可靠度。","textEn":"The cited technical guidance and research provide a reading pathway, not the engineering history of a particular facility. Examples, data and scene parameters are original teaching assumptions. When comparing conventional methods with integrated sensing, control and resource recovery, hold the treatment function and system boundary fixed before assessing efficiency and reliability."}],"connection":"以「冷量傳輸、壓降與低溫差診斷」為主線，依序完成十個專題單元。學徒在場景中辨識設備、列出邊界、重算明示的教學算例、比較量測與模型，最後診斷故障並交付證據。每一單元保留機制、算例、驗證與失效四種學習任務。","connectionEn":"Follow cooling transfer, pressure loss and low-temperature-difference diagnosis through ten technical units. Identify equipment in the scene, define boundaries, reproduce explicitly hypothetical examples, compare measurements with models, and diagnose faults before handing over evidence. Each unit contains mechanism, calculation, verification and failure tasks.","references":[{"id":"v17s-urban-district","title":"區域供冷系統原理","titleEn":"About District Cooling Systems","url":"https://wcms.emsd.gov.hk/en/energy_efficiency/DCS_in_HK/about_dcs/index.html","organization":"Hong Kong EMSD","accessed":"2026-10-23","publisher":"Hong Kong EMSD","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-heat","title":"現場能源與熱泵技術","titleEn":"Onsite Energy Technologies","url":"https://betterbuildingssolutioncenter.energy.gov/onsite-energy/technologies","organization":"US DOE","accessed":"2026-10-23","publisher":"US DOE","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"sourceIds":["v17s-urban-district","v17s-urban-heat"]}]},"vendors":{"courses":[],"vendors":[]}}};
